/**
 * The storage adapter interface.
 *
 * This indirection is the whole point of S08. Photographs are private files that
 * do not belong in MongoDB, and the eventual home is Supabase Storage (ADR-032).
 * But that project does not exist yet, and a slice should not be blocked on an
 * account — so uploads go through this interface, and the local driver writes to
 * disk. S13 adds a Supabase driver and changes the factory, not the callers.
 *
 * Keys are opaque strings generated by the server. A driver must never treat a
 * key as a user-supplied path.
 */

export interface StoredObject {
  data: Buffer;
  contentType: string;
}

export interface StorageDriver {
  /** Writes an object. Overwrites silently — keys are UUIDs, so a collision is a bug. */
  put(key: string, data: Buffer, contentType: string): Promise<void>;

  /** Returns the object, or `null` when the key does not exist. */
  get(key: string): Promise<StoredObject | null>;

  /** Deletes an object. Missing keys are not an error. */
  remove(key: string): Promise<void>;
}
